<?php
declare(strict_types=1);
session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=$_SESSION['role'];$uid=(int)$_SESSION['user_id'];
$creatorRoles=['system_admin'=>['sub_admin','admin','director'],'sub_admin'=>['admin','director'],'admin'=>['director'],'director'=>['sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher','driver','hr','storekeeper'],'sub_director'=>['headteacher','head_academic','assistant_academic','examination_officer','teacher','driver','hr','storekeeper'],'headteacher'=>['teacher']];$allowed=$creatorRoles[$role]??[];$error='';$saved=isset($_GET['saved']);$pdo=null;
try{$pdo=db();if(in_array($role,['system_admin','sub_admin'],true))$schools=$pdo->query('SELECT id,name FROM schools ORDER BY name')->fetchAll();else{$q=$pdo->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();}}catch(Throwable $ex){$schools=[];$error='School directory unavailable. Apply latest database/schema.sql.';}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!$allowed){http_response_code(403);exit('You cannot create accounts at this level.');}$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$newRole=(string)($_POST['role']??'');$password=(string)($_POST['password']??'');$schoolId=(int)($_POST['school_id']??0);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($newRole,$allowed,true)||strlen($password)<12){$error='Enter a name, valid email, allowed role, and initial password with at least 12 characters.';}elseif($schoolId&&!array_filter($schools,fn($s)=>(int)$s['id']===$schoolId)){$error='Choose a school within your access.';}elseif(!in_array($newRole,['system_admin','sub_admin','admin','director'],true)&&!$schoolId){$error='Choose a school for this school-based role.';}else{try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$newRole]);$newId=(int)$pdo->lastInsertId();if($schoolId){$m=$pdo->prepare("INSERT INTO school_memberships(school_id,user_id,scope) VALUES(?,?,'member')");$m->execute([$schoolId,$newId]);}$a=$pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$a->execute([$uid,'create','user',$newId,json_encode(['role'=>$newRole,'school_id'=>$schoolId?:null])]);$pdo->commit();header('Location: people.php?saved=1');exit;}catch(PDOException $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getCode()==='23000'?'That email already has an account.':'Account could not be created. Verify the database schema and try again.';}}}
$members=[];try{if(in_array($role,['system_admin','sub_admin'],true))$members=$pdo->query('SELECT u.id,u.name,u.email,u.role,u.status,GROUP_CONCAT(s.name ORDER BY s.name SEPARATOR \' · \') schools FROM users u LEFT JOIN school_memberships m ON m.user_id=u.id LEFT JOIN schools s ON s.id=m.school_id GROUP BY u.id ORDER BY u.created_at DESC LIMIT 300')->fetchAll();else{$q=$pdo->prepare('SELECT u.id,u.name,u.email,u.role,u.status,GROUP_CONCAT(s.name ORDER BY s.name SEPARATOR \' · \') schools FROM users u JOIN school_memberships mine ON mine.user_id=? JOIN school_memberships m ON m.user_id=u.id AND m.school_id=mine.school_id LEFT JOIN schools s ON s.id=m.school_id GROUP BY u.id ORDER BY u.name LIMIT 300');$q->execute([$uid]);$members=$q->fetchAll();}}catch(Throwable $ex){}
$roleLabels=['system_admin'=>'System admin','sub_admin'=>'Sub admin','admin'=>'Admin','director'=>'Director','sub_director'=>'School manager','headteacher'=>'Head of school','head_academic'=>'Head of academics','assistant_academic'=>'Assistant academic','examination_officer'=>'Examination officer','teacher'=>'Teacher','driver'=>'Driver','hr'=>'HR','storekeeper'=>'Stores'];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>People · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item active" href="people.php" aria-current="page">♧ &nbsp;People</a><a class="nav-item" href="notes.php">▤ &nbsp;Learning notes</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> People</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name'])?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">PEOPLE & ACCESS</div><h1>People</h1><p class="muted">Create role-based accounts and review staff in your school access.</p></div></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($saved):?><div class="notice success" role="status">Account created and access recorded.</div><?php endif;?><?php if($allowed):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">NEW ACCOUNT</div><h2>Invite a team member</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label for="name">Full name</label><input id="name" name="name" autocomplete="name" required maxlength="140"></div><div><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="190"></div><div><label for="role-choice">Role</label><select id="role-choice" name="role" required><option value="">Choose role</option><?php foreach($allowed as $r):?><option value="<?=e($r)?>"><?=e($roleLabels[$r])?></option><?php endforeach;?></select></div><?php if($schools):?><div><label for="school-id">School access</label><select id="school-id" name="school_id"><option value="">No school assigned</option><?php foreach($schools as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><?php endif;?><div><label for="initial-password">Initial password</label><input id="initial-password" name="password" type="password" minlength="12" autocomplete="new-password" required><small class="muted">At least 12 characters. Share it securely and have the user change it.</small></div></div><button class="button primary" type="submit">Create account</button></form></section><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">DIRECTORY</div><h2>Team accounts</h2></div><span class="count-pill"><?=count($members)?> people</span></div><?php if(!$members):?><div class="empty-state"><span class="empty-icon">♧</span><h3>No team accounts found</h3><p>Accounts within your school access will appear here.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>School</th><th>Status</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['email'])?></td><td><?=e($roleLabels[$m['role']]??$m['role'])?></td><td><?=e($m['schools']?:'System wide')?></td><td><?=e(ucfirst($m['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main></div></body></html>
